#define NEG_INF -1000000000

int cmp_desc(const void *a, const void *b) {
    return (*(int *)b) - (*(int *)a);
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int A[10];
    for (int i = 0; i < M; i++) scanf("%d", &A[i]);

    /* Matchsticks needed for digits 0..9 */
    int cost[10] = {0, 2, 5, 5, 4, 5, 6, 3, 7, 6};

    /* Sort allowed digits in descending order so reconstruction is lexicographically largest */
    qsort(A, M, sizeof(int), cmp_desc);

    /* dp[i] = maximum number of digits that can be formed using exactly i matchsticks */
    int *dp = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 0; i <= N; i++) dp[i] = NEG_INF;
    dp[0] = 0;

    for (int i = 0; i <= N; i++) {
        if (dp[i] < 0) continue;
        for (int j = 0; j < M; j++) {
            int d = A[j];
            int c = cost[d];
            if (i + c <= N && dp[i] + 1 > dp[i + c]) {
                dp[i + c] = dp[i] + 1;
            }
        }
    }

    /* Reconstruct answer */
    int rem = N;
    while (rem > 0) {
        for (int j = 0; j < M; j++) {
            int d = A[j];
            int c = cost[d];
            if (rem - c >= 0 && dp[rem - c] == dp[rem] - 1) {
                putchar('0' + d);
                rem -= c;
                break;
            }
        }
    }
    putchar('\n');

    free(dp);
    return 0;
}

