public class Main {
    static final int[] COST = {6,2,5,5,4,5,6,3,7,6}; // matches needed for digits 0..9

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        int[] digits = new int[M];
        for (int i = 0; i < M; i++) digits[i] = fs.nextInt();

        // Sort digits descending so reconstruction naturally prefers larger digits
        Integer[] arr = new Integer[M];
        for (int i = 0; i < M; i++) arr[i] = digits[i];
        Arrays.sort(arr, Collections.reverseOrder());
        for (int i = 0; i < M; i++) digits[i] = arr[i];

        // dp[i] = maximum number of digits that can be formed using exactly i matches
        int NEG = -1_000_000_000;
        int[] dp = new int[N + 1];
        Arrays.fill(dp, NEG);
        dp[0] = 0;

        for (int i = 0; i <= N; i++) {
            if (dp[i] < 0) continue;
            for (int d : digits) {
                int c = COST[d];
                if (i + c <= N) {
                    dp[i + c] = Math.max(dp[i + c], dp[i] + 1);
                }
            }
        }

        StringBuilder ans = new StringBuilder();
        int rem = N;

        // Reconstruct lexicographically largest among those with maximum length
        while (rem > 0) {
            for (int d : digits) {
                int c = COST[d];
                if (rem >= c && dp[rem - c] == dp[rem] - 1) {
                    ans.append(d);
                    rem -= c;
                    break;
                }
            }
        }

        System.out.println(ans.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

